<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class RolePermissionsSchema extends SchemaDefinition { protected string $table = 'role_permissions'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('role_id'); $table->foreignId('permission_id'); $table->timestamps(); $table->foreign('role_id')->references('id')->on('roles')->onDelete('CASCADE'); $table->foreign('permission_id')->references('id')->on('permissions')->onDelete('CASCADE'); $table->unique('role_id', 'permission_id'); } } 